insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('TJ', 'default', 'План счетов бухгалтерского учета финансово-хозяйственной деятельности хозяйствующих субъектов (распоряжение Минфина № 41 от 27.05.2011)', '{"en":"Chart of accounts of business entities (Ministry of Finance order No. 41 of 27 May 2011)"}'::jsonb, true, 'companies', array['TJ-BS', 'TJ-IS']::text[], null, 'Распоряжение Министерства финансов Республики Таджикистан от 27 мая 2011 года № 41 утверждает План счетов бухгалтерского учета финансово-хозяйственной деятельности хозяйствующих субъектов (приложение 1), обязательный с 1 января 2012 года и при национальных стандартах, и при МСФО. Коды и названия разделов 1–3 (активы, обязательства, собственный капитал) до счета 33300 включительно перенесены из опубликованного текста приложения 1; дальше текст в открытом доступе обрывается (счета 33400 и далее, разделы IV–VI — доходы и расходы). Счета доходов и расходов (44000, 55000, 66000) и перечисленные ниже счета десте — собственные: 10541, 10542, 22321, 22322, 22590, 44000, 44100, 44110, 44120, 44190, 44200, 44210, 44220, 44230, 55000, 55010, 55020, 55100, 55110, 55120, 55130, 55200, 55210, 55220, 55230, 55240, 55250, 55260, 55270, 55280, 55290, 55300, 55310, 55320, 55330, 55390, 66100, 66110, 66120, 66130, 66500, 66510, 66520, 66900. См. README.md.', 'coa-order-41')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

