  ('TJ', 'OPN', 'Журнал открытия', '{"en":"Opening journal"}'::jsonb, 'opening', 60),
  ('TJ', 'PUR', 'Журнал покупок', '{"en":"Purchase journal"}'::jsonb, 'purchase', 20),
  ('TJ', 'SAL', 'Журнал продаж', '{"en":"Sales journal"}'::jsonb, 'sales', 10)
on conflict (country, code) do update set
