insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('TJ', 'TJ-P-13', 'НДС 13 % — стандартная ставка с 2027 года (покупка)', '{"en":"VAT 13% — standard rate from 2027 (purchase)"}'::jsonb, null, 'percent', 13, 'purchase', 'domestic', date '2027-01-01', null, 'Налоговый кодекс, статья 264, часть 1, пункт 1), статья 397, часть 4 и статья 266, часть 1 — зачет налога по ставке 13 процентов с 1 января 2027 года.', null, null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-P-13-NR', 'НДС 13 % — услуги иностранного поставщика (налоговый агент, без зачета) с 2027 года', '{"en":"VAT 13% — services of a foreign supplier (tax agent, no credit) from 2027"}'::jsonb, 'НДС, который налоговый агент — получатель услуг иностранного поставщика — удерживает и уплачивает в бюджет без права зачета', 'percent', 13, 'purchase', 'foreign_services_received', date '2027-01-01', null, 'Налоговый кодекс, статья 260 и статья 397, часть 4 — то же правило по ставке 13 процентов с 1 января 2027 года.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-P-14', 'НДС 14 % — стандартная ставка (покупка)', '{"en":"VAT 14% — standard rate 2024–2026 (purchase)"}'::jsonb, null, 'percent', 14, 'purchase', 'domestic', date '2024-01-01', date '2026-12-31', 'Налоговый кодекс, статья 264, часть 1, пункт 1) и статья 266, часть 1 — при использовании стандартной ставки зачитывается налог, подлежащий уплате или уплаченный по счету-фактуре, если товары (работы, услуги) используются для предпринимательской деятельности.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-P-14-NR', 'НДС 14 % — услуги иностранного поставщика (налоговый агент, без зачета)', '{"en":"VAT 14% — services of a foreign supplier (tax agent, no credit)"}'::jsonb, 'НДС, который налоговый агент — получатель услуг иностранного поставщика — удерживает и уплачивает в бюджет без права зачета', 'percent', 14, 'purchase', 'foreign_services_received', date '2024-01-01', date '2026-12-31', 'Налоговый кодекс, статья 260 — при обратном налогообложении налоговый агент удерживает НДС из суммы, подлежащей выплате иностранному поставщику без постоянного места деятельности в Таджикистане, по ставкам статьи 264 (часть 3), и уплачивает его в бюджет в декларации за месяц операции без права зачета (часть 4); зарегистрированный агент включает налог в декларацию к уплате.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-13', 'НДС 13 % — стандартная ставка с 2027 года (продажа)', '{"en":"VAT 13% — standard rate from 2027 (sale)"}'::jsonb, null, 'percent', 13, 'sale', 'domestic', date '2027-01-01', null, 'Налоговый кодекс, статья 264, часть 1, пункт 1) и статья 397, часть 4 — стандартная ставка НДС 13 процентов с 1 января 2027 года (в редакции Закона от 11.02.2025 № 2143).', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-14', 'НДС 14 % — стандартная ставка (продажа)', '{"en":"VAT 14% — standard rate 2024–2026 (sale)"}'::jsonb, null, 'percent', 14, 'sale', 'domestic', date '2024-01-01', date '2026-12-31', 'Налоговый кодекс, статья 264, часть 1, пункт 1) и статья 397, часть 4 — стандартная ставка НДС 14 процентов с 1 января 2024 года до 31 декабря 2026 года (в редакции Закона от 11.02.2025 № 2143).', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-5', 'НДС 5 % — сниженная ставка: сельскохозяйственная продукция внутреннего производства, обучение, медицинские услуги санаториев (продажа)', '{"en":"VAT 5% — reduced rate: domestic agricultural products, education, sanatorium medical services (sale)"}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2025-02-11', null, 'Налоговый кодекс, статья 264, часть 1, пункт 2) — сниженная ставка 5 процентов для продажи сельскохозяйственных продуктов внутреннего производства, переработки продукции сельского хозяйства (кроме хлопка-сырца), услуг по обучению и медицинских услуг в санаториях и на курортах, без права на зачет налога (в редакции Закона от 11.02.2025 № 2143).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-7', 'НДС 7 % — сниженная ставка: строительные работы, гостиничные услуги, общественное питание (продажа)', '{"en":"VAT 7% — reduced rate: construction works, hotel services, catering (sale)"}'::jsonb, null, 'percent', 7, 'sale', 'domestic', date '2025-02-11', null, 'Налоговый кодекс, статья 264, часть 1, пункт 2) — сниженная ставка 7 процентов для строительных работ, гостиничных услуг и услуг общественного питания (в редакции Закона от 11.02.2025 № 2143); часть 5 — раздельный учет по налогооблагаемому обороту и налогооблагаемому ввозу. Зачет налога при сниженной ставке в статье 266 не предусмотрен (она называется «при использовании стандартной ставки»).', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-EXEMPT-FINANCIAL', 'Освобождено от НДС — финансовые услуги за вознаграждение (продажа)', '{"en":"VAT-exempt — financial services for a fee (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2024-01-01', null, 'Налоговый кодекс, статья 251, часть 2, пункт 2) — оказание финансовых услуг за вознаграждение освобождено от НДС; их перечень определяет Национальный банк Таджикистана по согласованию с Министерством финансов; в перечень входит и финансовая аренда (лизинг), кроме поставки ее предмета.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-EXEMPT-INTL-TRANSPORT', 'Освобождено от НДС — международные перевозки (продажа)', '{"en":"VAT-exempt — international transport (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2024-01-01', null, 'Налоговый кодекс, статья 252, часть 1 — транспортные и иные услуги, связанные с международными грузовыми и пассажирскими перевозками (один из пунктов отправления или назначения за пределами Республики Таджикистан), освобождены от НДС; освобождение, а не нулевая ставка.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-EXEMPT-REALESTATE', 'Освобождено от НДС — продажа, передача или аренда недвижимости (продажа)', '{"en":"VAT-exempt — sale, transfer or lease of real estate (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2024-01-01', null, 'Налоговый кодекс, статья 251, часть 2, пункт 1) — продажа, передача или аренда недвижимости освобождена от НДС, кроме гостиничных помещений и жилья для отдыхающих, новых построенных жилых помещений и недвижимого имущества, используемого для предпринимательских целей (подпункты а–в); часть 1 — освобожденная операция не считается налогооблагаемой.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('TJ', 'TJ-S-ZERO-EXPORT', 'НДС 0 % — экспорт товаров (продажа)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2024-01-01', null, 'Налоговый кодекс, статья 264, часть 2 и статья 254, часть 1 — экспорт товаров, кроме драгоценных металлов и камней, первичного алюминия, концентратов, товарной руды, лома металлов, хлопка и других товаров, перечисленных в части 1, облагается по нулевой ставке; при неподтверждении вывоза в течение 90 дней с даты регистрации под режимом «Экспорт» (часть 2) поставка облагается по положительной ставке.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

