insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('TJ', 'TJ-VAT', 'Декларация по налогу на добавленную стоимость', array['month']::declaration_period[], 'month'::declaration_period, date '2024-01-01', null, 'Налоговый кодекс, статья 273 — налоговый период по НДС — календарный месяц (для иностранных лиц, оказывающих физическим лицам дистанционные услуги, — квартал); статья 272 — декларация и уплата; статья 265 — налог к уплате в бюджет — положительная разница между налогом, исчисленным по стандартной ставке, и налогом к зачету по статье 266. Форма декларации и инструкция утверждаются уполномоченным государственным органом в сфере финансов (статья 272, часть 4); их текст не удалось прочитать из открытых источников, поэтому ячейки названы по статьям Кодекса (TAXABLE, REDUCED7, REDUCED5, ZERO, EXEMPT, REVERSE, TURNOVER, INPUT, CREDIT, PAYABLE, EXCESS), а не по номерам строк официальной формы. См. README.md.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Налоговый кодекс, статья 272, часть 1 — декларация по НДС представляется и налог уплачивается в бюджет не позднее 15-го числа месяца, следующего за отчетным периодом. Для иностранных лиц, оказывающих физическим лицам дистанционные услуги, срок — 20-е число (часть 2): этот срок формат одной строкой не выражает.', 'tax-code', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('TJ', 'TJ-VAT', 'TAXABLE', 'base', 'Операции по стандартной ставке (14 % до 2026 года, 13 % с 2027 года) — налогооблагаемый оборот', '{"en":"Standard-rate transactions — taxable turnover"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Налоговый кодекс, статья 264, часть 1, пункт 1) и часть 6; статья 248 — стоимость налогооблагаемой операции без НДС.', 'tax-code'),
