  numbering_legal_reference     = 'Налоговый кодекс, статья 269, части 2, 3 и 5 — счет-фактура по НДС и акцизам содержит порядковый номер, составляется в электронном виде и регистрируется в реестре через информационную программу налоговых органов; номер, присваиваемый этой системой, не зависит от внутренней нумерации коммерческого документа, формат которой закон не задает — последовательная нумерация дана как пример.',
  numbering_source_key          = 'tax-code',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Налоговый кодекс, статья 256, части 1–3 — датой налогооблагаемой операции считается момент выставления счета-фактуры по НДС и акцизам; если счет-фактура не выставлен до или в день операции — день приемки, продажи или передачи, а при перевозке — день отгрузки; аванс, по которому в течение пяти дней не выставлен счет-фактура, — дата аванса. Здесь заявлена основа правила (`invoice_if_issued`: счет-фактура, а без него — поставка); аванс и регулярные услуги (части 3–6) этим форматом не выражаются, см. README.md.',
  tax_point_source_key          = 'tax-code',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = 'Налоговый кодекс, статья 249 и статья 270 — изменение налогооблагаемого оборота (возврат, изменение цены) корректируется в отчетном периоде, в котором оно произошло, и оформляется дополнительным счетом-фактурой; проведенная запись не стирается, а исправляется корректирующим документом.',
  posted_edit_policy_source_key = 'tax-code',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Налоговый кодекс, статья 269, части 3 и 5 — счет-фактура по НДС и акцизам составляется в электронном виде, предоставляется покупателю в прямом (онлайн) режиме и хранится в электронной базе данных налоговых органов; плательщику НДС она выдается только в электронной форме. Это государственная информационная система налоговых органов, а не обмен по семантической модели EN 16931: профиль, схема участника и схема НДС не заданы, дата начала обязательства в прочитанном тексте не указана, а передача в систему остается вне ядра (README.md).',
  einvoice_source_key           = 'tax-code',
